/**
 * Fathu's puppet rig. Tune the slices and pivots here.
 * Coordinates are in pixels of the source cutout (approx. 175 x 512).
 * Each part is clipped from the image with its polygon and rotated around its pivot.
 * Left/right parts are generated by mirroring the "L" definitions around the image centre.
 */

export type Pt = [number, number];

export interface PartDef {
  poly: Pt[];
  pivot: Pt;
}

export interface RigDef {
  width: number;
  height: number;
  head: PartDef;
  torso: PartDef; // pivot = waist
  hips: PartDef; // pivot = pelvis (root)
  upperArmL: PartDef; // pivot = shoulder
  forearmL: PartDef; // pivot = elbow
  thighL: PartDef; // pivot = hip joint
  shinL: PartDef; // pivot = knee
  /** Length from knee pivot to boot sole, and hip pivot to knee pivot. */
  thighLen: number;
  shinLen: number;
}

