/** Foreshortening limits for any part's scaleY. */
export const RIG_LIMITS = { minScale: 0.4, maxScale: 1.15 };
/** Blend time constant between animation states (seconds). ~80ms to settle. */
export const RIG_BLEND_TAU = 0.026;

/**
 * Optional frame-by-frame sprites (back view, transparent, feet at the bottom).
 * If these files exist in /public/sprites they replace the rig for those states.
 */
const runMods = import.meta.glob("../assets/fathu_run_0*.png.asset.json", { eager: true, import: "default" }) as Record<string, { url: string }>;
const jumpMods = import.meta.glob("../assets/fathu_jump_0*.png.asset.json", { eager: true, import: "default" }) as Record<string, { url: string }>;
const urls = (m: Record<string, { url: string }>) => Object.keys(m).sort().map((k) => m[k].url);

/** Frames are drawn this much taller than playerHeight (frames include headroom for raised arms). */
export const FRAME_SCALE = 1.15;

export const OPTIONAL_FRAMES = {
  run: urls(runMods),
  jump: urls(jumpMods),
  slide: Array.from({ length: 5 }, (_, i) => `/sprites/fathu_slide_0${i + 1}.png`),
  roll: Array.from({ length: 5 }, (_, i) => `/sprites/fathu_roll_0${i + 1}.png`),
};

/**
 * THREE-LAYER back-view rig (used for every in-game back-view state).
 * Layers are cut from fathu_back with generous overlap and drawn legs -> torso -> head.
 * The whole sprite is NEVER scaled; only the thighs/shins foreshorten, the torso
 * pitches forward as a strip mesh, and the head moves at 100% size.
 * All values are source-image pixels (175 x 512, feet at y = 512).
 */
export const LAYER_RIG = {
  width: 175,
  height: 512,
  centerX: 88,
  /** Head + neck cut-out (never scaled). Pivot = neck base. */
  head: { poly: [[50, 0], [126, 0], [128, 60], [116, 96], [60, 96], [48, 60]] as Pt[], neckY: 90 },
  /** Torso with both arms. Pivot = hip line. */
  torso: {
    poly: [
      [24, 64], [151, 64], [156, 110], [175, 150], [175, 294], [134, 294], [136, 256],
      [40, 256], [42, 294], [0, 294], [0, 150], [19, 110],
    ] as Pt[],
    top: 64,
    bottom: 294,
  },
  /** Hips + legs + boots. */
  legs: { poly: [[38, 224], [138, 224], [148, 300], [154, 512], [20, 512], [28, 300]] as Pt[], top: 224 },
  hipY: 240,
  kneeY: 386,
  /** Horizontal strips used for the torso pitch mesh. */
  strips: 12,
  /** Perspective strength of the torso pitch (shoulders shrink as he leans). */
  pitchPerspective: 0.0045,
  /** How much of the forward lean reads as "up" on screen (camera is behind + above). */
  pitchRise: 0,
};
